import { test, expect } from '@playwright/test';

test.describe('Pagination Controls - Load Correct Page of Results', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should load the correct page of results when user clicks on pagination controls', async ({ page }) => {
    // Verify initial page is loaded
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify initial page number is displayed
    const pageNumber = page.getByRole('heading', { name: /page 1/i });
    await expect(pageNumber).toBeVisible();

    // Verify initial results are displayed
    const resultItem = page.getByRole('listitem', { name: /item 1/i });
    await expect(resultItem).toBeVisible();

    // Click on page 2 button
    const page2Button = page.getByRole('button', { name: /page 2/i });
    await page2Button.click();

    // Wait for page to load
    await page.waitForLoadState('networkidle');

    // Verify page number has changed to 2
    const pageNumber2 = page.getByRole('heading', { name: /page 2/i });
    await expect(pageNumber2).toBeVisible();

    // Verify results are updated
    const resultItem2 = page.getByRole('listitem', { name: /item 2/i });
    await expect(resultItem2).toBeVisible();

    // Verify page 2 button is disabled
    await expect(page2Button).toBeDisabled();

    // Click on page 3 button
    const page3Button = page.getByRole('button', { name: /page 3/i });
    await page3Button.click();

    // Wait for page to load
    await page.waitForLoadState('networkidle');

    // Verify page number has changed to 3
    const pageNumber3 = page.getByRole('heading', { name: /page 3/i });
    await expect(pageNumber3).toBeVisible();

    // Verify results are updated
    const resultItem3 = page.getByRole('listitem', { name: /item 3/i });
    await expect(resultItem3).toBeVisible();

    // Verify page 3 button is disabled
    await expect(page3Button).toBeDisabled();
  });

  test('should handle edge case when user clicks on disabled pagination button', async ({ page }) => {
    // Verify initial page is loaded
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify initial page number is displayed
    const pageNumber = page.getByRole('heading', { name: /page 1/i });
    await expect(pageNumber).toBeVisible();

    // Verify initial results are displayed
    const resultItem = page.getByRole('listitem', { name: /item 1/i });
    await expect(resultItem).toBeVisible();

    // Click on page 5 button (disabled)
    const page5Button = page.getByRole('button', { name: /page 5/i });
    await page5Button.click();

    // Verify page number does not change
    const pageNumber5 = page.getByRole('heading', { name: /page 5/i });
    await expect(pageNumber5).not.toBeVisible();

    // Verify page 5 button is still disabled
    await expect(page5Button).toBeDisabled();

    // Verify no error message is displayed
    const errorMessage = page.getByText(/page not available/i);
    await expect(errorMessage).not.toBeVisible();
  });
});
